#include <stdlib.h>
#include <string.h>
#include <float.h>
/* Jonker-Volgenant dense LAP. cost n x n row-major. x[i]=col of row i */
int lapjv(int n, const double *cost, int *rowsol) {
    int *colsol = malloc(n*sizeof(int));
    double *v = malloc(n*sizeof(double));
    int *free_ = malloc(n*sizeof(int));
    int *collist = malloc(n*sizeof(int));
    int *matches = calloc(n,sizeof(int));
    double *d = malloc(n*sizeof(double));
    int *pred = malloc(n*sizeof(int));
    int i,j,k,numfree=0,f,i0,j1,j2=0,endofpath=0,last=0,low,up,loopcnt,prvnumfree;
    double min=0,h,umin,usubmin,v2;
    /* column reduction */
    for (j=n-1;j>=0;j--) {
        min=cost[j]; int imin=0;
        for (i=1;i<n;i++) if (cost[i*n+j]<min){min=cost[i*n+j];imin=i;}
        v[j]=min;
        if (++matches[imin]==1){rowsol[imin]=j;colsol[j]=imin;}
        else if (v[j]<v[rowsol[imin]]) {int j1_=rowsol[imin];rowsol[imin]=j;colsol[j]=imin;colsol[j1_]=-1;}
        else colsol[j]=-1;
    }
    /* reduction transfer */
    for (i=0;i<n;i++) {
        if (matches[i]==0) free_[numfree++]=i;
        else if (matches[i]==1) {
            j1=rowsol[i]; min=DBL_MAX;
            const double *c=cost+(size_t)i*n;
            for (j=0;j<n;j++) if (j!=j1 && c[j]-v[j]<min) min=c[j]-v[j];
            v[j1]-=min;
        }
    }
    /* augmenting row reduction */
    loopcnt=0;
    do {
        loopcnt++;
        k=0; prvnumfree=numfree; numfree=0;
        while (k<prvnumfree) {
            i=free_[k++];
            const double *c=cost+(size_t)i*n;
            umin=c[0]-v[0]; j1=0; usubmin=DBL_MAX;
            for (j=1;j<n;j++){h=c[j]-v[j];
                if (h<usubmin){ if (h>=umin){usubmin=h;j2=j;} else {usubmin=umin;umin=h;j2=j1;j1=j;} } }
            i0=colsol[j1];
            if (umin<usubmin) v[j1]=v[j1]-(usubmin-umin);
            else if (i0>=0) {j1=j2;i0=colsol[j2];}
            rowsol[i]=j1; colsol[j1]=i;
            if (i0>=0) {
                if (umin<usubmin) free_[--k]=i0;
                else free_[numfree++]=i0;
            }
        }
    } while (loopcnt<2);
    /* augmentation */
    for (f=0;f<numfree;f++) {
        int freerow=free_[f];
        const double *c=cost+(size_t)freerow*n;
        for (j=n-1;j>=0;j--){d[j]=c[j]-v[j];pred[j]=freerow;collist[j]=j;}
        low=0;up=0;int unassignedfound=0;
        do {
            if (up==low) {
                last=low-1;
                min=d[collist[up++]];
                for (k=up;k<n;k++){j=collist[k];h=d[j];
                    if (h<=min){ if (h<min){up=low;min=h;} collist[k]=collist[up];collist[up++]=j; } }
                for (k=low;k<up;k++) if (colsol[collist[k]]<0){endofpath=collist[k];unassignedfound=1;break;}
            }
            if (!unassignedfound) {
                j1=collist[low++]; i=colsol[j1];
                const double *ci=cost+(size_t)i*n;
                h=ci[j1]-v[j1]-min;
                for (k=up;k<n;k++){j=collist[k];v2=ci[j]-v[j]-h;
                    if (v2<d[j]){pred[j]=i;
                        if (v2==min){ if (colsol[j]<0){endofpath=j;unassignedfound=1;break;}
                                      else {collist[k]=collist[up];collist[up++]=j;} }
                        d[j]=v2;}}
            }
        } while (!unassignedfound);
        for (k=0;k<=last;k++){j1=collist[k];v[j1]+=d[j1]-min;}
        do { i=pred[endofpath]; colsol[endofpath]=i; j1=endofpath; endofpath=rowsol[i]; rowsol[i]=j1; } while (i!=freerow);
    }
    free(colsol);free(v);free(free_);free(collist);free(matches);free(d);free(pred);
    return 0;
}
