#include <stdlib.h>
#include <string.h>
#include <float.h>
typedef struct { double d; int j; } HE;
static void hpush(HE *h, int *sz, double d, int j){
    int i=(*sz)++; while(i>0){int p=(i-1)>>1; if(h[p].d<=d)break; h[i]=h[p]; i=p;} h[i].d=d; h[i].j=j;}
static HE hpop(HE *h, int *sz){
    HE top=h[0]; HE last=h[--(*sz)]; int n=*sz,i=0;
    while(1){int l=2*i+1; if(l>=n)break; int r=l+1; int c=(r<n&&h[r].d<h[l].d)?r:l; if(h[c].d>=last.d)break; h[i]=h[c]; i=c;}
    if(n>0)h[i]=last; return top;}

/* returns number of rounds; col4row output */
int emd_assign(int n, const double *C, int K, int *row4col_out, int *col4row){
    int *adj = malloc(sizeof(int)*(size_t)n*n);
    int *deg = calloc(n,sizeof(int));
    unsigned char *in = calloc((size_t)n*n,1);
    double *u=malloc(n*sizeof(double)), *v=calloc(n,sizeof(double));
    int *row4col=malloc(n*sizeof(int));
    double *dist=malloc(n*sizeof(double)); int *pred=malloc(n*sizeof(int));
    unsigned char *done=calloc(n,1); double *seen_d=malloc(n*sizeof(double));
    int *fincols=malloc(n*sizeof(int)); int *touched=malloc(n*sizeof(int));
    HE *heap=malloc(sizeof(HE)*((size_t)n*n+n));
    int *freelist=malloc(n*sizeof(int));
    int i,j,k;
    if (K>n) K=n;
    /* kNN per row and per column */
    int *best=malloc(K*sizeof(int)); double *bd=malloc(K*sizeof(double));
    for(i=0;i<n;i++){ const double *c=C+(size_t)i*n; int m=0;
        for(j=0;j<n;j++){ double x=c[j]; if(m<K){int p=m++; while(p>0&&bd[p-1]>x){bd[p]=bd[p-1];best[p]=best[p-1];p--;} bd[p]=x;best[p]=j;}
            else if(x<bd[K-1]){int p=K-1; while(p>0&&bd[p-1]>x){bd[p]=bd[p-1];best[p]=best[p-1];p--;} bd[p]=x;best[p]=j;} }
        for(k=0;k<m;k++){j=best[k]; if(!in[(size_t)i*n+j]){in[(size_t)i*n+j]=1; adj[(size_t)i*n+deg[i]++]=j;}} }
    for(j=0;j<n;j++){ int m=0;
        for(i=0;i<n;i++){ double x=C[(size_t)i*n+j]; if(m<K){int p=m++; while(p>0&&bd[p-1]>x){bd[p]=bd[p-1];best[p]=best[p-1];p--;} bd[p]=x;best[p]=i;}
            else if(x<bd[K-1]){int p=K-1; while(p>0&&bd[p-1]>x){bd[p]=bd[p-1];best[p]=best[p-1];p--;} bd[p]=x;best[p]=i;} }
        for(k=0;k<m;k++){i=best[k]; if(!in[(size_t)i*n+j]){in[(size_t)i*n+j]=1; adj[(size_t)i*n+deg[i]++]=j;}} }
    free(best);free(bd);
    for(i=0;i<n;i++){col4row[i]=-1;row4col[i]=-1;}
    int nfree=0; for(i=0;i<n;i++) freelist[nfree++]=i;
    /* initial u */
    for(i=0;i<n;i++){double m=DBL_MAX; for(k=0;k<deg[i];k++){j=adj[(size_t)i*n+k]; double r=C[(size_t)i*n+j]-v[j]; if(r<m)m=r;} u[i]=m;}
    for(j=0;j<n;j++) seen_d[j]=DBL_MAX;
    int rounds=0;
    while(1){
        rounds++;
        for(int f=0;f<nfree;f++){
            int cur=freelist[f];
          retry:;
            int hs=0, nfin=0, ntouch=0, sink=-1; double minVal=0;
            /* relax from cur */
            { const double *c=C+(size_t)cur*n; int *a=adj+(size_t)cur*n;
              for(k=0;k<deg[cur];k++){j=a[k]; double r=c[j]-u[cur]-v[j];
                if(seen_d[j]==DBL_MAX) touched[ntouch++]=j;
                if(r<seen_d[j]){seen_d[j]=r;pred[j]=cur;hpush(heap,&hs,r,j);} } }
            while(hs>0){
                HE e=hpop(heap,&hs); j=e.j; if(done[j]||e.d>seen_d[j]) continue;
                done[j]=1; fincols[nfin++]=j; dist[j]=e.d;
                if(row4col[j]<0){sink=j;minVal=e.d;break;}
                int i2=row4col[j]; const double *c=C+(size_t)i2*n; int *a=adj+(size_t)i2*n; double base=e.d - (c[j]-u[i2]-v[j]);
                for(k=0;k<deg[i2];k++){int jj=a[k]; if(done[jj])continue; double r=base + c[jj]-u[i2]-v[jj];
                    if(seen_d[jj]==DBL_MAX) touched[ntouch++]=jj;
                    if(r<seen_d[jj]){seen_d[jj]=r;pred[jj]=i2;hpush(heap,&hs,r,jj);} }
            }
            if(sink<0){
                /* reset, densify cur row */
                for(k=0;k<ntouch;k++){seen_d[touched[k]]=DBL_MAX;}
                for(k=0;k<nfin;k++) done[fincols[k]]=0;
                const double *c=C+(size_t)cur*n; double m=DBL_MAX;
                for(j=0;j<n;j++){ if(!in[(size_t)cur*n+j]){in[(size_t)cur*n+j]=1; adj[(size_t)cur*n+deg[cur]++]=j;} double r=c[j]-v[j]; if(r<m)m=r; }
                u[cur]=m;
                goto retry;
            }
            /* update duals */
            u[cur]+=minVal;
            for(k=0;k<nfin;k++){j=fincols[k]; if(j==sink)continue; int i2=row4col[j]; u[i2]+=minVal-dist[j]; v[j]-=minVal-dist[j];}
            /* augment */
            j=sink; while(1){int i2=pred[j]; row4col[j]=i2; int t=col4row[i2]; col4row[i2]=j; if(i2==cur)break; j=t;}
            for(k=0;k<ntouch;k++) seen_d[touched[k]]=DBL_MAX;
            for(k=0;k<nfin;k++) done[fincols[k]]=0;
        }
        /* dense check */
        nfree=0;
        for(i=0;i<n;i++){ const double *c=C+(size_t)i*n; double ui=u[i]; int viol=0;
            for(j=0;j<n;j++){ if(c[j]-ui-v[j] < -1e-13){ viol=1; if(!in[(size_t)i*n+j]){in[(size_t)i*n+j]=1; adj[(size_t)i*n+deg[i]++]=j;} } }
            if(viol){ j=col4row[i]; row4col[j]=-1; col4row[i]=-1; freelist[nfree++]=i;
                double m=DBL_MAX; for(k=0;k<deg[i];k++){int jj=adj[(size_t)i*n+k]; double r=c[jj]-v[jj]; if(r<m)m=r;} u[i]=m; } }
        if(nfree==0) break;
    }
    if(row4col_out) memcpy(row4col_out,row4col,n*sizeof(int));
    free(adj);free(deg);free(in);free(u);free(v);free(row4col);free(dist);free(pred);free(done);free(seen_d);free(fincols);free(touched);free(heap);free(freelist);
    return rounds;
}
