static inline void addedge(S *s,int i,int j){ size_t q=(size_t)i*s->n+j; if(!s->in[q]){s->in[q]=1; s->adj[(size_t)i*s->n+s->deg[i]++]=j;} }

static void setu(S *s,int i){ const double *c=s->C+(size_t)i*s->n; int *a=s->adj+(size_t)i*s->n; double m=DBL_MAX;
    for(int k=0;k<s->deg[i];k++){int j=a[k]; double r=c[j]-s->v[j]; if(r<m)m=r;} s->u[i]=m; }

static void augment(S *s,int cur){
