        s->done[j]=1; s->fincols[nfin++]=j; s->dist[j]=e.d;
        if(s->row4col[j]<0){sink=j;minVal=e.d;break;}
        int i2=s->row4col[j]; const double *c=C+(size_t)i2*n; int *a=s->adj+(size_t)i2*n; double base=e.d-(c[j]-u[i2]-v[j]);
        double ui=u[i2];
        for(k=0;k<s->deg[i2];k++){int jj=a[k]; if(s->done[jj])continue; double r=base+c[jj]-ui-v[jj];
            if(r<s->seen_d[jj]){ if(s->seen_d[jj]==DBL_MAX) s->touched[ntouch++]=jj; s->seen_d[jj]=r;s->pred[jj]=i2;hpush(s->heap,&hs,r,jj);} }
