    for(k=0;k<nfin;k++) s->done[s->fincols[k]]=0;
    if(sink<0){
        for(j=0;j<n;j++) addedge(s,cur,j);
        setu(s,cur);
        goto retry;
    }
    u[cur]+=minVal;
    for(k=0;k<nfin;k++){j=s->fincols[k]; if(j==sink)continue; int i2=s->row4col[j]; double dd=minVal-s->dist[j]; u[i2]+=dd; v[j]-=dd;}
    j=sink; while(1){int i2=s->pred[j]; s->row4col[j]=i2; int t=s->col4row[i2]; s->col4row[i2]=j; if(i2==cur)break; j=t;}
}

static void topk(const double *c, int n, int K, int *best, double *bd, int *m_out){
    int m=0;
    for(int j=0;j<n;j++){ double x=c[j];
        if(m<K){int p=m++; while(p>0&&bd[p-1]>x){bd[p]=bd[p-1];best[p]=best[p-1];p--;} bd[p]=x;best[p]=j;}
        else if(x<bd[K-1]){int p=K-1; while(p>0&&bd[p-1]>x){bd[p]=bd[p-1];best[p]=best[p-1];p--;} bd[p]=x;best[p]=j;} }
    *m_out=m;
}

int emd_assign(int n, const double *C, const double *CT, int K, int *col4row){
    S s; s.n=n; s.C=C;
    s.adj=malloc(sizeof(int)*(size_t)n*n); s.deg=calloc(n,sizeof(int)); s.in=calloc((size_t)n*n,1);
    s.u=malloc(n*sizeof(double)); s.v=calloc(n,sizeof(double));
    s.row4col=malloc(n*sizeof(int)); s.col4row=col4row;
    s.dist=malloc(n*sizeof(double)); s.pred=malloc(n*sizeof(int)); s.done=calloc(n,1);
    s.seen_d=malloc(n*sizeof(double)); s.fincols=malloc(n*sizeof(int)); s.touched=malloc(n*sizeof(int));
    s.heap=malloc(sizeof(HE)*((size_t)n*n+n));
    int i,j,k,m;
    if(K>n)K=n;
    int *best=malloc(K*sizeof(int)); double *bd=malloc(K*sizeof(double));
    for(i=0;i<n;i++){ topk(C+(size_t)i*n,n,K,best,bd,&m); for(k=0;k<m;k++) addedge(&s,i,best[k]); }
    for(j=0;j<n;j++){ topk(CT+(size_t)j*n,n,K,best,bd,&m); for(k=0;k<m;k++) addedge(&s,best[k],j); }
    free(best);free(bd);
    for(i=0;i<n;i++){col4row[i]=-1;s.row4col[i]=-1;s.seen_d[i]=DBL_MAX;}
    /* column-min init for v */
    for(j=0;j<n;j++){ const double *c=CT+(size_t)j*n; double mm=DBL_MAX; for(i=0;i<n;i++) if(c[i]<mm)mm=c[i]; s.v[j]=mm; }
    for(i=0;i<n;i++) setu(&s,i);
    for(i=0;i<n;i++) augment(&s,i);
    int rounds=1;
    while(1){
        int changed=0;
        for(i=0;i<n;i++){ const double *c=C+(size_t)i*n; double ui=s.u[i]; int viol=0;
            for(j=0;j<n;j++){ if(c[j]-ui-s.v[j] < -1e-12){ viol=1; addedge(&s,i,j);} }
            if(viol){ changed=1; j=col4row[i]; s.row4col[j]=-1; col4row[i]=-1; setu(&s,i); augment(&s,i);} }
        if(!changed)break;
        rounds++;
    }
    free(s.adj);free(s.deg);free(s.in);free(s.u);free(s.v);free(s.row4col);free(s.dist);free(s.pred);free(s.done);free(s.seen_d);free(s.fincols);free(s.touched);free(s.heap);
    return rounds;
}
