{"command": "export TMPDIR=$PWD/tmp; cat > fast.c <<'EOF'
#include <stdlib.h>
#include <string.h>
#include <float.h>

static int cap=0;
static unsigned char *in; static int *col; static double *cst; static int *deg;
static double *LB,*tmp,*p,*psave; static int *row4col,*stack;

static void ensure(int n){
    if(n<=cap) return;
    free(in);free(col);free(cst);free(deg);free(LB);free(tmp);free(p);free(psave);free(row4col);free(stack);
    in=malloc((size_t)n*n); col=malloc((size_t)n*n*sizeof(int)); cst=malloc((size_t)n*n*sizeof(double));
    deg=malloc(n*sizeof(int)); LB=malloc(n*sizeof(double)); tmp=malloc(n*sizeof(double));
    p=malloc(n*sizeof(double)); psave=malloc(n*sizeof(double)); row4col=malloc(n*sizeof(int)); stack=malloc(n*sizeof(int));
    cap=n;
}

/* Gauss-Seidel label correcting: lower prices until c[i,col4row[i]]+p[col4row[i]] <= c[i,k]+p[k] for all i,k. */
static int certify(int n,const double *C,const int *col4row,double *p){
    for(int sweep=0; sweep<=n+1; sweep++){
        int changed=0;
        for(int i=0;i<n;i++){
            const double *c=C+(size_t)i*n; int j=col4row[i];
            double m=DBL_MAX; for(int k=0;k<n;k++){ double x=c[k]+p[k]; m = x<m? x: m; }
            double t=m-c[j];
            if(t<p[j]-1e-12){ p[j]=t; changed=1; }
        }
        if(!changed) return 1;
    }
    return 0;
}

#define ADDE(I,J) do{ size_t q_=(size_t)(I)*n+(J); if(!in[q_]){in[q_]=1; col[(size_t)(I)*n+deg[I]]=(J); cst[(size_t)(I)*n+deg[I]]=C[q_]; deg[I]++;} }while(0)

/* returns 0 on certified success, 1 on failure */
int emd_assign(int n,const double *C,double eps0,double epsf,double fac,double addw,int *col4row){
    int i,j,k;
    ensure(n);
    memset(in,0,(size_t)n*n);
    for(i=0;i<n;i++){deg[i]=0; LB[i]=-DBL_MAX; p[i]=DBL_MAX;}
    for(i=0;i<n;i++){ const double *c=C+(size_t)i*n; for(j=0;j<n;j++){ double x=c[j]; p[j]= x<p[j]? x: p[j]; } }
    for(j=0;j<n;j++) p[j]=-p[j];
    double eps=eps0; int sp; int first=1;
    while(1){
        sp=0;
        if(first){ for(i=0;i<n;i++){col4row[i]=-1;row4col[i]=-1;} for(i=n-1;i>=0;i--) stack[sp++]=i; first=0; }
        else for(i=n-1;i>=0;i--){ j=col4row[i]; const int *cl=col+(size_t)i*n; const double *cs=cst+(size_t)i*n; int dg=deg[i];
            double w1=DBL_MAX, wj=0; for(k=0;k<dg;k++){ double x=cs[k]+p[cl[k]]; if(x<w1)w1=x; if(cl[k]==j) wj=x; }
            if(wj>w1+eps || w1>LB[i]){ row4col[j]=-1; col4row[i]=-1; stack[sp++]=i; } }
        while(sp>0){
            i=stack[sp-1];
            double w1=DBL_MAX,w2=DBL_MAX; int j1=-1;
            const int *cl=col+(size_t)i*n; const double *cs=cst+(size_t)i*n; int dg=deg[i];
            for(k=0;k<dg;k++){ double x=cs[k]+p[cl[k]]; if(x<w2){ if(x<w1){w2=w1;w1=x;j1=cl[k];} else w2=x; } }
            if(w2>LB[i]){
                const double *c=C+(size_t)i*n;
                for(k=0;k<n;k++) tmp[k]=c[k]+p[k];
                double thr;
                if(w2<DBL_MAX) thr=w2+addw*eps;
                else { double t1=DBL_MAX,t2=DBL_MAX; for(k=0;k<n;k++){ double x=tmp[k]; if(x<t2){ if(x<t1){t2=t1;t1=x;} else t2=x; } } thr=t2+addw*eps; }
                const unsigned char *inr=in+(size_t)i*n;
                for(k=0;k<n;k++){ if(tmp[k]<=thr && !inr[k]) ADDE(i,k); }
                double lb=DBL_MAX;
                for(k=0;k<n;k++){ double y = inr[k]? DBL_MAX: tmp[k]; lb = y<lb? y: lb; }
                LB[i]=lb;
                continue;
            }
            sp--;
            p[j1]+= w2-w1+eps;
            int o=row4col[j1]; row4col[j1]=i; col4row[i]=j1;
            if(o>=0){col4row[o]=-1; stack[sp++]=o;}
        }
        if(eps<=epsf){
            memcpy(psave,p,n*sizeof(double));
            if(certify(n,C,col4row,p)) return 0;
            memcpy(p,psave,n*sizeof(double));
            if(eps<1e-14) return 1;
        }
        eps*=fac;
    }
}
