#include <stdlib.h>
#include <string.h>
#include <float.h>
#include <math.h>
#include <immintrin.h>

static int capd=0; static float *Cf,*pf; static int *r4c,*stk; static double *pd,*pds; static int *cl2; static double *cs2; static int *off2;
static void ensure(int n){
    if(n<=capd)return;
    free(Cf);free(pf);free(r4c);free(stk);free(pd);free(pds);free(cl2);free(cs2);free(off2);
    int np=(n+7)&~7;
    Cf=aligned_alloc(32,(size_t)n*np*sizeof(float)); pf=aligned_alloc(32,np*sizeof(float));
    r4c=malloc(n*sizeof(int)); stk=malloc(n*sizeof(int)); pd=malloc(n*sizeof(double)); pds=malloc(n*sizeof(double));
    cl2=malloc((size_t)n*n*sizeof(int)); cs2=malloc((size_t)n*n*sizeof(double)); off2=malloc((n+1)*sizeof(int));
    capd=n;
}

static int certify(int n,const double *C,const int *col4row,double *p,double tau){
    for(int round=0; round<6; round++){
        int ne=0, viol=0;
        for(int i=0;i<n;i++){
            const double *c=C+(size_t)i*n; int j=col4row[i]; double base=c[j]+p[j]; double th=base+tau;
            off2[i]=ne;
            for(int k=0;k<n;k++){ double x=c[k]+p[k]; if(x<th && k!=j){ cl2[ne]=k; cs2[ne]=c[k]-c[j]; ne++; if(x<base-1e-12) viol=1; } }
        }
        off2[n]=ne;
        if(!viol) return 1;
        int ok=0;
        for(int sweep=0; sweep<=n+1; sweep++){
            int changed=0;
            for(int i=0;i<n;i++){ int j=col4row[i]; double m=p[j];
                for(int e=off2[i];e<off2[i+1];e++){ double t=p[cl2[e]]+cs2[e]; if(t<m) m=t; }
                if(m<p[j]-1e-12){ p[j]=m; changed=1; } }
            if(!changed){ok=1;break;}
        }
        if(!ok) return 0;
        tau*=4;
    }
    return 0;
}

/* returns 0 if certified optimal */
int dense_assign(int n,const double *C,double eps0,double epsf,double fac,int *col4row){
    ensure(n);
    int np=(n+7)&~7, i,j,k;
    for(i=0;i<n;i++){ const double *c=C+(size_t)i*n; float *f=Cf+(size_t)i*np; for(k=0;k<n;k++) f[k]=(float)c[k]; for(;k<np;k++) f[k]=1e30f; }
    for(k=0;k<np;k++) pf[k]=0;
    /* init prices: -colmin */
    for(k=0;k<n;k++) pf[k]=1e30f;
    for(i=0;i<n;i++){ float *f=Cf+(size_t)i*np; for(k=0;k<n;k++) pf[k]= f[k]<pf[k]? f[k]: pf[k]; }
    for(k=0;k<n;k++) pf[k]=-pf[k];
    for(i=0;i<n;i++){col4row[i]=-1;r4c[i]=-1;}
    float eps=(float)eps0; int first=1;
    const __m256i idx0=_mm256_setr_epi32(0,1,2,3,4,5,6,7);
    while(1){
        int sp=0;
        if(first){ for(i=n-1;i>=0;i--) stk[sp++]=i; first=0; }
        else for(i=n-1;i>=0;i--){ j=col4row[i]; float *f=Cf+(size_t)i*np;
            __m256 vm=_mm256_set1_ps(1e30f);
            for(k=0;k<np;k+=8) vm=_mm256_min_ps(vm,_mm256_add_ps(_mm256_load_ps(f+k),_mm256_load_ps(pf+k)));
            float a[8]; _mm256_storeu_ps(a,vm); float w1=a[0]; for(int q=1;q<8;q++) w1=a[q]<w1?a[q]:w1;
            if(f[j]+pf[j]>w1+eps){ r4c[j]=-1; col4row[i]=-1; stk[sp++]=i; } }
        while(sp>0){
            i=stk[--sp]; const float *f=Cf+(size_t)i*np;
            __m256 m1=_mm256_set1_ps(1e30f), m2=m1; __m256i im=_mm256_setzero_si256(), vi=idx0; const __m256i v8=_mm256_set1_epi32(8);
            for(k=0;k<np;k+=8){
                __m256 x=_mm256_add_ps(_mm256_load_ps(f+k),_mm256_load_ps(pf+k));
                __m256 lt=_mm256_cmp_ps(x,m1,_CMP_LT_OQ);
                m2=_mm256_min_ps(m2,_mm256_max_ps(x,m1));
                m1=_mm256_min_ps(m1,x);
                im=_mm256_castps_si256(_mm256_blendv_ps(_mm256_castsi256_ps(im),_mm256_castsi256_ps(vi),lt));
                vi=_mm256_add_epi32(vi,v8);
            }
            float a1[8],a2[8]; int ia[8]; _mm256_storeu_ps(a1,m1); _mm256_storeu_ps(a2,m2); _mm256_storeu_si256((__m256i*)ia,im);
            float w1=a1[0],w2=a2[0]; int j1=ia[0];
            for(int q=1;q<8;q++){ if(a1[q]<w1){ w2= w1<a2[q]? w1: a2[q]; w1=a1[q]; j1=ia[q]; } else { float t=a1[q]<a2[q]?a1[q]:a2[q]; w2 = t<w2? t: w2; } }
            pf[j1]+= (w2-w1)+eps;
            int o=r4c[j1]; r4c[j1]=i; col4row[i]=j1;
            if(o>=0){col4row[o]=-1; stk[sp++]=o;}
        }
        if(eps<=epsf) break;
        eps*=fac; if(eps<epsf) eps=epsf;
    }
    for(k=0;k<n;k++) pd[k]=pf[k];
    return certify(n,C,col4row,pd,20.0*eps+1e-6)?0:1;
}
