                    IM[q]=_mm256_castps_si256(_mm256_blendv_ps(_mm256_castsi256_ps(IM[q]),_mm256_castsi256_ps(VI[q]),lt));
                    VI[q]=_mm256_add_epi32(VI[q],v32);
