/* row min + argmin of c - v (double) */
static inline double rowmin(const double *c,const double *v,int n,int *arg){
    int n4=n&~3; __m256d m=_mm256_set1_pd(DBL_MAX); __m256i im=_mm256_set1_epi64x(0), vi=_mm256_setr_epi64x(0,1,2,3), v4=_mm256_set1_epi64x(4);
