        m=_mm256_min_pd(m,x); im=_mm256_castpd_si256(_mm256_blendv_pd(_mm256_castsi256_pd(im),_mm256_castsi256_pd(vi),lt)); vi=_mm256_add_epi64(vi,v4); }
    double a[4]; long long ia[4]; _mm256_storeu_pd(a,m); _mm256_storeu_si256((__m256i*)ia,im);
    double best=a[0]; int bj=(int)ia[0];
    for(int q=1;q<4;q++) if(a[q]<best||(a[q]==best&&ia[q]<bj)){best=a[q];bj=(int)ia[q];}
    for(int k=n4;k<n;k++){ double x=c[k]-v[k]; if(x<best){best=x;bj=k;} }
    *arg=bj; return best;
}

int dense_assign(int n,const double *C,double eps0,double epsf,double fac,double u1,double u2,double u3,double u4,int *rowsol){
